WITH `query_dump` AS (SELECT get_query_dump('select * from t1', TRUE) AS `x`) SELECT get_json_string(`query_dump`.`x`, get_json_string(`query_dump`.`x`, '$.statement')) AS `get_json_string(x, get_json_string(query_dump.x, '$.statement'))` FROM `query_dump`;
WITH `query_dump` AS (SELECT get_query_dump('select * from t1', TRUE) AS `x`) SELECT get_json_string(`query_dump`.`x`, '$.statement') AS `get_json_string(x, '$.statement')` FROM `query_dump`;
WITH `query_dump` AS (SELECT get_query_dump('select * from t1', TRUE) AS `x`) SELECT CAST((get_json_string(`query_dump`.`x`, '$.statement')) AS ARRAY<VARCHAR(1)>) AS `CAST((get_json_string(x, '$.statement')) AS ARRAY<VARCHAR(1)>)` FROM `query_dump`;
WITH `query_dump` AS (SELECT get_query_dump('select * from t1', TRUE) AS `x`) SELECT get_json_string(`query_dump`.`x`, '$.statement') AS `get_json_string(x, '$.statement')` FROM `query_dump`;